insert into CREDIT_ASSETPOOL_DETAIL ( SEQNO, FINPROD_ID, CREATE_USER, CREATE_DEPT, CREATE_TIME, UPDATE_USER, UPDATE_TIME ) select t1.seqno, t1.finprodId, t1.createUser, t1.createDept, t1.createTime, t1.updateUser, t1.updateTime from (
select #{item.seqno, jdbcType=VARCHAR} seqno, #{item.finprodId, jdbcType=VARCHAR} finprodId, #{item.createUser, jdbcType=VARCHAR} createUser, #{item.createDept, jdbcType=VARCHAR} createDept, #{item.createTime, jdbcType=TIMESTAMP} createTime, #{item.updateUser, jdbcType=VARCHAR} updateUser, #{item.updateTime, jdbcType=TIMESTAMP} updateTime from DUAL
)t1

